def encrypt(s):
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            # Shift down by 2 places, modulo 26
            shifted = (ord(char) - ord('a') - 2) % 26 + ord('a')
            result += chr(shifted)
        elif 'A' <= char <= 'Z':
            # Shift down by 2 places, modulo 26
            shifted = (ord(char) - ord('A') - 2) % 26 + ord('A')
            result += chr(shifted)
        else:
            result += char
    return result

